/// <summary>
/// Result of comparing a single field between expected and actual values.
/// </summary>
public sealed record FieldComparisonResult(
    string FieldName,
    decimal Expected,
    decimal Actual,
    decimal Difference,
    bool Passed
);

/// <summary>
/// Result of comparing a complete test fixture.
/// </summary>
public sealed record TestComparisonResult
{
    public required string TestId { get; init; }
    public required string Description { get; init; }
    public required bool Passed { get; init; }
    public required IReadOnlyList<FieldComparisonResult> FieldResults { get; init; }
    public string? ErrorMessage { get; init; }

    public IEnumerable<FieldComparisonResult> FailedFields =>
        FieldResults.Where(f => !f.Passed);
}
